const app=document.querySelector('#app');
let menu,view='boards',selected=1,editing=null;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null||n===undefined?'—':'$'+Number(n).toFixed(2);
const screenOptions=(value)=>menu.screens.map(s=>`<option value="${s.id}" ${s.id===Number(value)?'selected':''}>TV ${s.physicalPosition} · ${e(s.name)}</option>`).join('');
const param=new URLSearchParams(location.search);const display=param.has('screen');
function notify(text){const el=document.querySelector('#status');el.textContent=text;el.style.display='block';setTimeout(()=>el.style.display='none',3500)}
function board(screen){const items=menu.items.filter(i=>i.screenId===screen.id&&i.visible).sort((a,b)=>a.sortOrder-b.sortOrder);const promos=menu.promotions.filter(p=>p.screenId===screen.id&&p.visible).sort((a,b)=>a.sortOrder-b.sortOrder);return `<section class="board ${e(screen.layout)}" aria-label="TV ${screen.physicalPosition}: ${e(screen.name)}"><div class="board-head"><span>${e(menu.brand.name)}</span><span>${e(screen.name)}</span></div><div class="board-items">${!screen.visible?'<p class="empty">Menu temporarily unavailable</p>':items.map(i=>{const asset=menu.assets.find(a=>a.id===i.imageAssetId);return `<article class="item"><h2>${e(i.name)}</h2>${i.price!==null?`<div class="price">${money(i.price)}</div>`:''}${!i.available?'<div class="unavailable">Not available</div>':''}${asset?.src?`<div class="image-wrap"><img class="food" src="${e(asset.src)}" alt="${e(i.name)}"></div>`:'<div class="placeholder">Photo to be supplied</div>'}${i.variants.map(v=>`<div class="variant"><span>${e(v.label)}</span><strong>${money(v.price)}</strong></div>`).join('')}${i.combo?`<div class="combo">${e(i.combo.label)} +${money(i.combo.priceDelta)}</div>`:''}${i.description?`<p class="description">${e(i.description)}</p>`:''}</article>`}).join('')}</div>${screen.visible&&promos.length?`<div class="board-footer">${promos.map(p=>`<span>${e(p.text)}</span>`).join('')}</div>`:''}</section>`}
function render(){document.documentElement.style.setProperty('--red',menu.brand.colours.red);document.documentElement.style.setProperty('--charcoal',menu.brand.colours.charcoal);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(display){document.body.classList.add('display');const s=menu.screens.find(s=>s.physicalPosition===Number(param.get('screen')));app.innerHTML=s?board(s):'<p>Screen not found.</p>';return;}if(view==='boards')renderBoards();if(view==='admin')renderAdmin();if(view==='notes')renderNotes();}
function renderBoards(){const s=menu.screens.find(s=>s.id===selected)||menu.screens[0];app.innerHTML=`<div class="heading"><div><h1>Four screens. One menu.</h1><p class="muted">Current menu content, transcribed from your restaurant’s boards.</p></div><button id="fullscreen">Full screen</button></div><div class="screen-tabs">${[...menu.screens].sort((a,b)=>a.physicalPosition-b.physicalPosition).map(s=>`<button data-screen="${s.id}" class="${s.id===selected?'active':''}">TV ${s.physicalPosition}<small>${e(s.name)}</small></button>`).join('')}</div>${board(s)}<div class="caption"><span>Source: ${e(s.sourceFile)} · Left-to-right placement inferred from neighboring boards.</span><span>Artwork placeholders · Prices as photographed</span></div><p class="muted">Prototype edits last for this session. Export your menu to keep changes; use Import in Edit menu to restore them.</p>`;app.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.screen);render()});app.querySelector('#fullscreen').onclick=()=>{const boardEl=app.querySelector('.board');if(boardEl.requestFullscreen)boardEl.requestFullscreen().catch(()=>notify('Full screen is unavailable in this preview.'));};}
function renderAdmin(){app.innerHTML=`<div class="heading"><div><h1>Edit menu</h1><p class="muted">${menu.items.length} products · All four boards use this shared menu data.</p></div><label class="actions">Import menu<input id="import" type="file" accept="application/json" style="width:220px"></label></div><div class="notice">Changes apply to this preview session. Export the menu to keep them. This initial mockup does not synchronize remote TVs.</div>${editing?editor(menu.items.find(i=>i.id===editing)):''}<div class="panel scroll-table"><table><thead><tr><th>Product</th><th>Price / options</th><th>Screen</th><th>Status</th><th></th></tr></thead><tbody>${[...menu.items].sort((a,b)=>a.screenId-b.screenId||a.sortOrder-b.sortOrder).map(i=>`<tr><td>${e(i.name)}<small>${e(i.category)}</small></td><td>${i.price!==null?money(i.price):i.variants.map(v=>e(v.label)+' '+money(v.price)).join(' / ')}${i.combo?`<small>${e(i.combo.label)} +${money(i.combo.priceDelta)}</small>`:''}</td><td>TV ${menu.screens.find(s=>s.id===i.screenId)?.physicalPosition}</td><td>${!i.visible?'Hidden':i.available?'Available':'Not available'}</td><td><button data-edit="${e(i.id)}">Edit<span class="source-name"> ${e(i.name)}</span></button></td></tr>`).join('')}</tbody></table></div><div class="panel"><h2>Screen mapping</h2><p class="muted">Move a whole board by changing its physical TV position. Individual products can move independently.</p><form id="mapping">${menu.screens.map(s=>`<label>${e(s.name)} · ${e(s.sourceFile)}<select name="s${s.id}">${[1,2,3,4].map(n=>`<option ${n===s.physicalPosition?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<button class="primary" type="submit">Apply mapping</button></form></div><div class="panel"><h2>Complete menu data</h2><p class="muted">Edit promotions, category labels, sizes, descriptions, add-ons, assets, screen names and layouts here. Unknown values stay null.</p><details><summary>Open structured data editor</summary><form id="rawform"><label class="full">Menu JSON<textarea id="raw" rows="20" spellcheck="false">${e(JSON.stringify(menu,null,2))}</textarea></label><button class="primary">Apply menu data</button></form></details></div>`;app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{editing=b.dataset.edit;renderAdmin();app.querySelector('#itemform').scrollIntoView({behavior:'smooth',block:'start'})});app.querySelector('#mapping').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),positions=menu.screens.map(s=>Number(f.get('s'+s.id)));if(new Set(positions).size!==4)return notify('Give each board a different TV position.');menu.screens.forEach((s,n)=>s.physicalPosition=positions[n]);render();notify('Screen mapping updated.');};app.querySelector('#rawform').onsubmit=ev=>{ev.preventDefault();try{const next=JSON.parse(app.querySelector('#raw').value);validate(next);menu=next;editing=null;render();notify('Menu data applied.');}catch(err){notify('Could not apply: '+err.message)}};app.querySelector('#import').onchange=async ev=>{try{const file=ev.target.files[0];if(!file)return;const next=JSON.parse(await file.text());validate(next);menu=next;editing=null;render();notify('Menu imported.');}catch(err){notify('Could not import: '+err.message)}};if(editing)bindEditor();}
function editor(i){return `<div class="panel"><h2>${e(i.name)}</h2><form id="itemform"><label>Product name<input name="name" required value="${e(i.name)}"></label><label>Category<input name="category" required value="${e(i.category)}"></label><label>Price (leave blank for sizes)<input type="number" name="price" min="0" step="0.01" value="${i.price??''}"></label><label>Screen<select name="screenId">${screenOptions(i.screenId)}</select></label><label>Order on screen<input type="number" name="sortOrder" min="1" required value="${i.sortOrder}"></label><label>Combo surcharge<input type="number" name="comboPrice" min="0" step="0.01" value="${i.combo?.priceDelta??''}"></label><label class="full">Description<textarea name="description">${e(i.description)}</textarea></label>${i.variants.map((v,n)=>`<label>${e(v.label)} price<input type="number" min="0" step="0.01" required name="variant${n}" value="${v.price}"></label>`).join('')}<label class="check"><input type="checkbox" name="visible" ${i.visible?'checked':''}>Visible on menu</label><label class="check"><input type="checkbox" name="available" ${i.available?'checked':''}>Available</label><div class="full actions"><button class="primary" type="submit">Apply changes</button><button type="button" id="cancel">Cancel</button><span class="muted">Source: ${e(i.source.file)}</span></div></form></div>`}
function bindEditor(){app.querySelector('#cancel').onclick=()=>{editing=null;renderAdmin()};app.querySelector('#itemform').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),i=menu.items.find(i=>i.id===editing);i.name=f.get('name').trim();i.category=f.get('category').trim();i.description=f.get('description').trim();i.price=f.get('price')===''?null:Number(f.get('price'));i.screenId=Number(f.get('screenId'));i.sortOrder=Number(f.get('sortOrder'));i.visible=f.has('visible');i.available=f.has('available');i.variants.forEach((v,n)=>v.price=Number(f.get('variant'+n)));i.combo=f.get('comboPrice')===''?null:{...(i.combo||{label:'COMBO!',includes:null}),priceDelta:Number(f.get('comboPrice'))};editing=null;renderAdmin();notify('Changes applied to the menu preview.');};}
function renderNotes(){app.innerHTML=`<div class="heading"><div><h1>Source notes</h1><p class="muted">The photos are reference material. Every displayed word and price is application data.</p></div></div><div class="notes-grid"><div class="panel"><h2>Confirm before production</h2><ul>${menu.developmentNotes.map(n=>`<li>${e(n.text)}</li>`).join('')}</ul></div><div><div class="panel"><h2>Assets needed</h2><p class="muted">No screenshot crops are used as production artwork. Temporary photo spaces mark the missing assets.</p><ul><li>Official Mr. Fez logo and fez icon in SVG or transparent PNG.</li><li>Original food photography for all ${menu.items.length} products, including family platters.</li><li>Drink photography and exact included drink options, if displayed later.</li><li>Original family meal promotional artwork and confirmed Instagram handle.</li><li>Brand font files or font names, and official colour values.</li></ul><a href="assets-needed.md">Read asset checklist</a></div><div class="panel"><h2>Visual direction</h2><p>Red and white product blocks on charcoal; condensed uppercase headings, prominent prices, cutout food photography and simple size-price rows. The prototype keeps these recognizable patterns with consistent spacing.</p><p class="muted">Fonts and colours are approximations. The blue cast on TV 1 is not treated as a confirmed brand colour.</p></div><div class="panel"><h2>Extraction record</h2><a href="extraction.md">Full transcription and screen hierarchy</a> · <a href="data/menu.json">Original seed data</a></div></div></div>`;}
function validate(m){const fail=t=>{throw Error(t)};if(m.schemaVersion!==1||!m.brand?.name||!m.brand.colours||!Array.isArray(m.items)||!Array.isArray(m.screens)||m.screens.length!==4)fail('Expected a version 1 menu with four screens.');if(!Array.isArray(m.assets)||!Array.isArray(m.promotions)||!Array.isArray(m.developmentNotes))fail('Missing assets, promotions or notes.');const ids=new Set(m.screens.map(s=>s.id));if(ids.size!==4||new Set(m.screens.map(s=>s.physicalPosition)).size!==4||m.screens.some(s=>![1,2,3,4].includes(s.physicalPosition)||!['columns','two-column','two-row','family'].includes(s.layout)||typeof s.name!=='string'))fail('Invalid screen mapping or layout.');const price=p=>p===null||(typeof p==='number'&&Number.isFinite(p)&&p>=0);if(new Set(m.items.map(i=>i.id)).size!==m.items.length)fail('Product IDs must be unique.');for(const i of m.items){if(!i.id||typeof i.name!=='string'||!i.name.trim()||typeof i.category!=='string'||typeof i.description!=='string'||!ids.has(i.screenId)||!Number.isFinite(i.sortOrder)||!price(i.price)||typeof i.visible!=='boolean'||typeof i.available!=='boolean'||!Array.isArray(i.variants)||!i.source?.file)fail('Invalid product: '+i.id);for(const v of i.variants)if(typeof v.label!=='string'||!price(v.price))fail('Invalid size price.');if(i.combo&&(!price(i.combo.priceDelta)||typeof i.combo.label!=='string'))fail('Invalid combo.');}for(const p of m.promotions)if(!ids.has(p.screenId)||typeof p.text!=='string')fail('Invalid promotion.');for(const a of m.assets)if(a.src&&!/^(https:\/\/|\.?\/?assets\/)/.test(a.src))fail('Asset URLs must use HTTPS or the local assets folder.');for(const c of Object.values(m.brand.colours))if(!/^#[0-9a-f]{6}$/i.test(c))fail('Colours must be six-digit hex values.');return true;}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;editing=null;render()});document.querySelector('#export').onclick=()=>{const blob=new Blob([JSON.stringify(menu,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mr-fez-menu.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Menu exported.');};
try{const r=await fetch('data/menu.json');if(!r.ok)throw Error('Menu data could not be loaded.');menu=await r.json();validate(menu);render();}catch(err){app.innerHTML=`<div class="panel"><h1>Menu unavailable</h1><p>${e(err.message)}</p><button onclick="location.reload()">Try again</button></div>`;}
